(7243000, 1123267, 175946, '<td valign="top">Great find for the challenge and looks like it may have been a good choice for HDR as the background looks just a little bright while some areas are just a little dark.</td>', 'Great find for the challenge and looks like it may have been a good choice for HDR as the background looks just a little bright while some areas are just a little dark.', '2014-07-21 21:01:30.000000', NULL, 1),
(7243001, 1123086, 175946, '<td valign="top">Great find for the challenge but a real challenge to capture. The roof part looks just slightly overexposed on this monitor but real killer is that darn pole that tends to divide the image. Maybe a different pov and exposure bias -.07 might have given better results.</td>', 'Great find for the challenge but a real challenge to capture. The roof part looks just slightly overexposed on this monitor but real killer is that darn pole that tends to divide the image. Maybe a different pov and exposure bias -.07 might have given better results.', '2014-07-21 21:04:22.000000', NULL, 1),
(7243003, 1123332, 175946, '<td valign="top">Great finds for the challenge but guessing you might have done better to have picked just one of these and moved in closer.</td>', 'Great finds for the challenge but guessing you might have done better to have picked just one of these and moved in closer.', '2014-07-21 21:06:46.000000', NULL, 1),
(7243004, 1122978, 175946, '<td valign="top">Sure does tell a story. Wonder if cropping some (a lot) of the right might have given better results. The poles and the green do not add much in my opinion.</td>', 'Sure does tell a story. Wonder if cropping some (a lot) of the right might have given better results. The poles and the green do not add much in my opinion.', '2014-07-21 21:08:27.000000', NULL, 1),
