(7243007, 1123044, 175946, '<td valign="top">Wondering if you considered using a fill flash as some parts are a bit dark.</td>', 'Wondering if you considered using a fill flash as some parts are a bit dark.', '2014-07-21 21:10:20.000000', NULL, 1),
(7243008, 1122975, 175946, '<td valign="top">Really liked this one and played with it some. Found if I cropped a little off the bottom, almost up the black part of the wall on the left, it made more of a leading line in and cropping a lot off the right side made the subject on the left much stronger for me. But then cropping is such a matter of personal choice.</td>', 'Really liked this one and played with it some. Found if I cropped a little off the bottom, almost up the black part of the wall on the left, it made more of a leading line in and cropping a lot off the right side made the subject on the left much stronger for me. But then cropping is such a matter of personal choice.', '2014-07-21 21:16:19.000000', NULL, 1),
(7243009, 1123327, 175946, '<td valign="top">Great title! Would have liked just a little closer look.</td>', 'Great title! Would have liked just a little closer look.', '2014-07-21 21:19:38.000000', NULL, 1),
