INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7243371, 1122492, 97225, '<td valign="top">Grim. One hopes that those who have abandoned it have not done so via escape.</td>', 'Grim. One hopes that those who have abandoned it have not done so via escape.', '2014-07-22 23:16:18.000000', NULL, 1),
(7243373, 1122621, 97225, '<td valign="top">I like the muted colours which contribute to the feeling of fading into the oblivion of the past.</td>', 'I like the muted colours which contribute to the feeling of fading into the oblivion of the past.', '2014-07-22 23:18:11.000000', NULL, 1),
(7243374, 1122964, 97225, '<td valign="top">Evokes something tragic. Is this in a war zone? One of my ribbon choices.</td>', 'Evokes something tragic. Is this in a war zone? One of my ribbon choices.', '2014-07-22 23:19:30.000000', NULL, 1),
(7243375, 1123280, 97225, '<td valign="top">An eerie ''after people'' feel. Well found. One of my ribbon choices.<br/>Bumping that to blue.</td>', 'An eerie ''after people'' feel. Well found. One of my ribbon choices.Bumping that to blue.', '2014-07-22 23:20:37.000000', NULL, 1),
(7243376, 1123273, 97225, '<td valign="top">Lovely photo. I have a feeling that he might have to wait for discovery by a new generation.</td>', 'Lovely photo. I have a feeling that he might have to wait for discovery by a new generation.', '2014-07-22 23:22:24.000000', NULL, 1),
(7243377, 1123342, 97225, '<td valign="top">An evocation of truth and sadness and the hard economic facts of life.</td>', 'An evocation of truth and sadness and the hard economic facts of life.', '2014-07-22 23:24:30.000000', NULL, 1),
(7243378, 1122876, 97225, '<td valign="top">Fascinating subject. Interesting pp.</td>', 'Fascinating subject. Interesting pp.', '2014-07-22 23:25:40.000000', NULL, 1),
